import json,pathlib,html
out=pathlib.Path.home()/'.local/share/oma/voice-preview'
d=json.loads((out/'samples.json').read_text())
regions={'quartz':'Australian · feminine','ripple':'Australian · masculine','vesper':'British · masculine','cedar':'Current OMA voice','willow':'Irish · feminine','stone':'Irish · masculine','gleam':'North American · feminine','meridian':'North American · masculine','bossa':'Brazilian Portuguese · feminine','tempo':'Brazilian Portuguese · masculine','beacon':'Filipino English · masculine','delta':'Southern US · feminine','cinder':'Southern US · masculine','marin':'API default'}
rows=[]
for x in d['samples']:
 desc=regions.get(x['id'],'') if not x['id'].startswith('vesper-') else 'Experimental prompt · same Vesper voice'
 body=('<audio controls preload="metadata" src="'+x['file']+'"></audio>') if 'file' in x else '<p class="error">'+html.escape(x['error'])+'</p>'
 rows.append('<article data-name="'+x['id']+'"><div><h3>'+html.escape(x['label'].title())+'</h3><p>'+desc+'</p></div>'+body+'<details><summary>Prompt & transcript</summary><p>'+html.escape(x['style'])+'</p><p lang="ja">'+html.escape(x.get('transcript',''))+'</p></details></article>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>O.M.A. — Voice Studio</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101310;color:#e4eadf;font:16px/1.6 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:48px 28px}header{border-bottom:1px solid #384033;padding-bottom:26px}.eyebrow{color:#9abd83;letter-spacing:3px;font-size:12px}h1{font-weight:500;font-size:42px;margin:10px 0}h2{font-size:23px;font-weight:500;margin:38px 0 15px}h3{margin:0;font-size:20px;font-weight:500}p{color:#aeb8a6;margin:7px 0}a{color:#b4dc96}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px 8px;border-bottom:1px solid #30372d}th{font-weight:500}input{width:100%;padding:13px;background:#191e16;border:1px solid #45533a;color:inherit;font:inherit;margin:8px 0 20px;border-radius:5px}select,textarea,button{font:inherit;color:inherit;background:#191e16;border:1px solid #45533a;border-radius:5px;padding:12px}select,textarea{display:block;width:100%;margin:8px 0 16px}button{cursor:pointer;background:#c1ddaa;color:#152010}button:disabled{opacity:.5}label{display:block} .grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}article{padding:20px;background:#191e16;border:1px solid #30392b;border-radius:8px}article p{font-size:13px;min-height:21px}audio{width:100%;margin:14px 0 0;height:40px}details{font-size:12px;margin-top:12px;color:#aeb8a6}summary{cursor:pointer}.error{color:#efad96}footer{margin-top:35px;font-size:13px}@media(max-width:650px){main{padding:28px 16px}.grid{grid-template-columns:1fr}h1{font-size:32px}td,th{font-size:13px}}</style>
<main><header><span class="eyebrow">O.M.A. / GPT-LIVE-1</span><h1>Voice Studio</h1><p>Compare voices, then explore delivery. Every sample was generated by GPT-Live.</p><p lang="ja">指示をお待ちしています。システムは正常です。次の操作を指定してください。</p><p>Voice samples: original PCM · 24 kHz · normal speed · silence trimmed only. The vocoder comparison below adds processing. AI-generated speech.</p></header>
<section id="effects"><h2>Effects lab</h2><p>Cedar · original preview vocoder method. Processing order: Vocoder → Radio → Reverb.</p><p>Radio: 300–3,400 Hz. Reverb: subtle, short metallic ambience (delay network, not a physical plate simulation). No additional API calls.</p><div class="grid"><article><h3>Original</h3><audio controls preload="metadata" src="fx-cedar-0.wav"></audio></article><article><h3>Vocoder 50%</h3><audio controls preload="metadata" src="fx-cedar-1.wav"></audio></article><article><h3>Radio</h3><audio controls preload="metadata" src="fx-cedar-2.wav"></audio></article><article><h3>Vocoder + Radio</h3><audio controls preload="metadata" src="fx-cedar-3.wav"></audio></article><article><h3>Reverb</h3><audio controls preload="metadata" src="fx-cedar-4.wav"></audio></article><article><h3>Vocoder + Reverb</h3><audio controls preload="metadata" src="fx-cedar-5.wav"></audio></article><article><h3>Radio + Reverb</h3><audio controls preload="metadata" src="fx-cedar-6.wav"></audio></article><article><h3>All three</h3><audio controls preload="metadata" src="fx-cedar-7.wav"></audio></article></div><article style="margin-top:16px"><h3>Current OMA · Streaming</h3><p>Cedar + Vocoder 50% + Radio. Short-window FFT processing; not identical to the original offline version.</p><audio controls preload="metadata" src="cedar-streaming-radio.wav"></audio></article><h3 style="margin-top:24px">Build a combination</h3><form id="effects-form"><label for="effects-voice">Voice</label><select id="effects-voice"><option value="alloy">Alloy</option><option value="ash">Ash</option><option value="ballad">Ballad</option><option value="beacon">Beacon</option><option value="bossa">Bossa</option><option value="cedar" selected>Cedar</option><option value="cinder">Cinder</option><option value="coral">Coral</option><option value="delta">Delta</option><option value="echo">Echo</option><option value="gleam">Gleam</option><option value="marin">Marin</option><option value="meridian">Meridian</option><option value="quartz">Quartz</option><option value="ripple">Ripple</option><option value="sage">Sage</option><option value="shimmer">Shimmer</option><option value="stone">Stone</option><option value="tempo">Tempo</option><option value="verse">Verse</option><option value="vesper">Vesper</option><option value="willow">Willow</option></select><label for="effects-mix">Vocoder mix</label><select id="effects-mix"><option value="0">Off</option><option value="0.35">35%</option><option value="0.5" selected>50%</option><option value="1">100%</option></select><label><input style="width:auto;margin:8px" type="checkbox" id="effects-radio"> Radio</label><label><input style="width:auto;margin:8px" type="checkbox" id="effects-reverb"> Reverb</label><button id="render-effects">Render combination</button><p id="effects-result" role="status"></p><audio id="effects-audio" hidden controls></audio></form><p>The eight comparisons above retain the original offline method. OMA now uses the low-latency streaming variant below.</p></section><section id="vocoder"><h2>Vocoder comparison</h2><p>The original Vesper comparison, restored exactly. Offline FFT vocoder with matched RMS levels.</p><div class="grid"><article><h3>Original</h3><p>No vocoder</p><audio controls preload="metadata" src="vocoder-original.wav"></audio></article><article><h3>Light</h3><p>35% vocoder · 65% original voice</p><audio controls preload="metadata" src="vocoder-light.wav"></audio></article><article><h3>Medium</h3><p>50% vocoder · 50% original voice</p><audio controls preload="metadata" src="vocoder-medium.wav"></audio></article><article><h3>Strong</h3><p>100% vocoder · fixed 110 Hz carrier · 24 bands</p><audio controls preload="metadata" src="vocoder-strong.wav"></audio></article></div><p>Original offline preview preserved. OMA uses a short-window streaming approximation for faster responses; output volume is 300%.</p></section><h2>What you can control</h2><table><tr><th>Control</th><th>How</th><th>Limits</th></tr><tr><td>Voice</td><td>Built-in voice selection</td><td>New session required to change voice</td></tr><tr><td>Tone & pace</td><td>Instructions: calm, warm, restrained, slow, brisk</td><td>Model interpretation; no exact timing guarantee</td></tr><tr><td>Language & pronunciation</td><td>Language instructions and pronunciation cues</td><td>Audition each voice in your language</td></tr><tr><td>Backchannels & interruptions</td><td>Conversation instructions</td><td>Evaluate during live conversation</td></tr><tr><td>Numeric speed / pitch</td><td>No documented GPT-Live parameter found</td><td>Retro delivery below is a prompt experiment</td></tr><tr><td>Custom voice</td><td>Authorized custom voice ID</td><td>Requires access and consent; not a stock preset</td></tr></table>
<h2>Try your own direction</h2><form id="custom"><label for="voice">Voice</label><select id="voice"><option value="vesper">vesper</option><option value="marin">marin</option><option value="alloy">alloy</option><option value="ash">ash</option><option value="ballad">ballad</option><option value="beacon">beacon</option><option value="bossa">bossa</option><option value="cedar" selected>cedar</option><option value="cinder">cinder</option><option value="coral">coral</option><option value="delta">delta</option><option value="echo">echo</option><option value="gleam">gleam</option><option value="meridian">meridian</option><option value="quartz">quartz</option><option value="ripple">ripple</option><option value="sage">sage</option><option value="shimmer">shimmer</option><option value="stone">stone</option><option value="tempo">tempo</option><option value="verse">verse</option><option value="willow">willow</option></select><label for="direction">Speaking instructions</label><textarea id="direction" rows="4" maxlength="4000" placeholder="例：昔のSF映画のコンピュータのように、低めで抑揚を抑え、ゆっくり明瞭に話してください。"></textarea><button id="generate">Generate preview</button><p>Uses GPT-Live API credits. Japanese or English instructions are welcome. Voice and style only; OMA settings stay unchanged.</p><p id="result" role="status"></p><audio id="custom-audio" controls hidden></audio></form><h2>Listen & compare</h2><p>Press play on a voice. Playing another sample pauses the previous one. OMA's selected voice is unchanged.</p><input id="search" aria-label="Filter voices" placeholder="Filter voices or styles…"><div class="grid">'''+''.join(rows)+'''</div><footer>Sources: <a href="https://developers.openai.com/api/docs/guides/live-conversations">GPT-Live sessions & voices</a> · <a href="https://developers.openai.com/api/docs/guides/live-prompting">GPT-Live prompting</a><p>Voice catalogue: OpenAI SDK 7.23.0. Successful previews confirm API acceptance on this account. Regional descriptions are influences, not language restrictions.</p></footer></main><script>document.querySelector('#effects-form').addEventListener('submit',async e=>{e.preventDefault();const button=document.querySelector('#render-effects'),status=document.querySelector('#effects-result'),player=document.querySelector('#effects-audio');button.disabled=true;status.textContent='Rendering…';try{const response=await fetch('/effects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({voice:document.querySelector('#effects-voice').value,vocoder:Number(document.querySelector('#effects-mix').value),radio:document.querySelector('#effects-radio').checked,reverb:document.querySelector('#effects-reverb').checked})});const data=await response.json();if(!response.ok)throw Error(data.error);player.src=data.file;player.hidden=false;player.load();status.textContent='Ready — press play to listen.';}catch(error){status.textContent=error.message}finally{button.disabled=false}});document.querySelector('#custom').addEventListener('submit',async e=>{e.preventDefault();const button=document.querySelector('#generate'),result=document.querySelector('#result'),player=document.querySelector('#custom-audio');button.disabled=true;result.textContent='Generating…';try{const response=await fetch('/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({voice:document.querySelector('#voice').value,style:document.querySelector('#direction').value})});const data=await response.json();if(!response.ok)throw Error(data.error);player.src=data.file;player.hidden=false;result.textContent=data.transcript;player.load();}catch(error){result.textContent=error.message}finally{button.disabled=false}});document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO')document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()})},true);document.querySelector('#search').addEventListener('input',e=>document.querySelectorAll('article').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(e.target.value.toLowerCase())));</script></html>'''
(out/'index.html').write_text(page)
print(str(out/'index.html'))
